using System;
namespace PathOfDawn.Core
{
    public static class GospelStudyQuestions
    {
        // Optional branches add context without consuming or awarding a Scripture reading.
        public static string[] For(string id)
        {
            switch(id)
            {
                case "road-bethlehem": return new[]{"왜 베들레헴으로 갔나요?","요셉은 다윗의 집 족속이었기 때문에 다윗의 동네인 베들레헴으로 향했단다. 호적 명령으로 사람들이 각각 고향으로 돌아가던 때였지. 누가복음 2장 3–5절을 이어 읽어 보렴.","나사렛과 베들레헴은 다른 곳인가요?","그렇단다. 나사렛은 갈릴리의 동네이고 베들레헴은 유대에 있는 다윗의 동네로 소개돼. 요셉과 마리아는 나사렛에서 베들레헴으로 갔다가, 뒤에 다시 나사렛으로 돌아오지."};
                case "night-shepherds": return new[]{"목자들은 무엇을 하고 있었나요?","밤에 밖에서 자기 양 떼를 지키고 있었단다. 누가는 그들이 특별한 잔치에 모여 있었다고 말하지 않고, 양을 돌보던 자리에서 소식을 만났다고 전해.","왜 먼저 무서워 말라고 했나요?","주의 사자가 곁에 서고 주의 영광이 둘러 비추자 목자들이 크게 무서워했기 때문이지. 그 다음에 큰 기쁨의 좋은 소식이 전해져. 두려움과 소식을 이어 읽으면 흐름을 알 수 있어."};
                case "manger-witnesses": return new[]{"목자들은 무엇을 찾아갔나요?","주께서 알리신 일을 보려고 베들레헴으로 갔어. 빨리 가서 마리아와 요셉과 구유에 누인 아기를 찾았단다. 그 구유가 앞서 들은 표적과 이어지지.","목자들이 전한 말은 무엇인가요?","본문은 이 아기에 대하여 자기들에게 이른 말을 알렸다고 전해. 듣는 사람들은 그 말을 기이하게 여겼고, 마리아는 그 모든 말을 마음에 지키어 생각했단다."};
                case "name-jesus": return new[]{"이름은 언제 지었나요?","누가는 할례할 팔일이 되매 이름을 예수라 하였다고 기록했단다. 짧은 한 절이지만 그때와 이름, 그 이름이 앞서 알려졌다는 사실이 함께 들어 있어.","그 이름은 미리 알려졌나요?","그렇단다. 이 절은 수태하기 전에 천사의 일컬은 바라고 설명하지. 예수님이 다른 사람에서 예수님으로 바뀐 이야기가 아니라, 탄생한 아기가 같은 이름으로 자라 가는 이야기야."};
                case "temple-dedication": return new[]{"아기 때에도 성전에 왔나요?","결례의 날이 차자 부모가 아기를 데리고 예루살렘에 올라왔단다. 지금 열두 살의 방문과는 다른 때의 일이야. 두 방문을 나누어 기억하면 같은 장소의 이야기가 더 분명해져.","본문에는 어떤 제물이 나오나요?","비둘기 한 쌍이나 어린 반구 둘이라고 적혀 있단다. 누가는 주의 율법에 말씀하신 대로 제사하려 했다고 그 이유도 함께 알려 주고 있어."};
                case "simeon-peace": return new[]{"시므온은 무엇을 보았다고 했나요?","내 눈이 주의 구원을 보았다고 고백했단다. 이어서 모든 백성 앞에 예비하신 것이라고 말하지. 그 고백은 아래 본문에서 직접 읽을 수 있어.","어떤 빛이라고 표현했나요?","이방을 비추는 빛이며 주의 백성 이스라엘의 영광이라고 했단다. 그림 속 햇빛보다 넓은 뜻을 지닌 표현이지. 시므온이 아기를 안고 한 찬송의 말들을 함께 읽어 보렴."};
                case "anna-thanksgiving": return new[]{"안나는 어떤 사람으로 소개되나요?","아셀 지파 바누엘의 딸 안나라는 선지자로 소개돼. 성전을 떠나지 않고 금식하며 기도함으로 밤낮 섬겼다고 기록되어 있단다.","안나는 누구에게 아기에 대해 말했나요?","하나님께 감사하고 예루살렘의 구속됨을 바라는 모든 사람에게 이 아기에 대하여 말했어. 소식을 듣고 기다리던 사람들에게 이어지는 만남이지."};
                default: return new[]{"가족은 어디로 돌아갔나요?","갈릴리로 돌아가 본 동네 나사렛에 이르렀다고 기록되어 있단다. 베들레헴에서의 탄생과 아기 때 성전 방문 뒤에 나사렛으로 돌아가는 흐름이 이어져.","어린 시절을 어떻게 기록했나요?","아기가 자라며 강하여지고 지혜가 충족하며 하나님의 은혜가 그 위에 있었다고 전해. 모든 어린 날을 자세히 설명하지는 않지만, 성장에 관한 이 문장을 남겨 두었단다."};
            }
        }
    }
}
